module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);
    reg [3:0] SP;
    reg [3:0] stack_mem_reg[3:0];
    reg [3:0] dataOut_reg;
    integer i;
    always @(posedge Clk or posedge Rst) begin
        if (Rst) begin
            SP <= 4'd4;
            for (i = 0; i < 4; i = i + 1) begin
                stack_mem_reg[i] <= 4'h0;
            end
        end 
        else if (EN == 1'b1) begin
            case ({RW})
                1'b0: begin 
                    if (!FULL) begin
                        stack_mem_reg[SP - 1] <= dataIn;
                        SP <= SP - 1;
                    end
                end

                1'b1: begin 
                    if (!EMPTY) begin
                        dataOut_reg <= stack_mem_reg[SP];
                        stack_mem_reg[SP] <= 4'h0;
                        SP <= SP + 1;
                    end
                end
            endcase
        end
    end

    assign EMPTY = (SP == 4'd4) ? 1'b1 : 1'b0;
    assign FULL = (SP == 4'd0) ? 1'b1 : 1'b0;
    assign dataOut = dataOut_reg;
endmodule
